<?php require __DIR__.'/config.php'; if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $email=strtolower(trim($_POST['email'])); $stmt=$db->prepare('SELECT id FROM users WHERE email=?'); $stmt->execute([$email]); $user=$stmt->fetch(PDO::FETCH_ASSOC); if ($user) { $token=bin2hex(random_bytes(24)); $db->prepare('UPDATE users SET reset_token_hash=?,reset_expires_at=? WHERE id=?')->execute([password_hash($token,PASSWORD_DEFAULT),time()+900,$user['id']]); error_log('[DEMO MAIL] Reset-Link: http://127.0.0.1/login/reset-password.php?token='.$token); } flash('Wenn die E-Mail existiert, wurde ein Reset-Link versendet.'); } page('<h1>Passwort zurücksetzen</h1>'.show_flash().'<form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><label>E-Mail<input type="email" name="email" required></label><button>Reset-Link anfordern</button></form>'); ?>